-- A different person shares an active row's name (checked 2026-09-23):
-- Michael Adams (AVC Trustee Area 4) is NOT the active "Michael Adams" row e4f4c7bc (Kentucky Secretary of State, R).
SET LOCAL essentials.allow_duplicate_name = 'on';
INSERT INTO essentials.politicians (id, first_name, last_name, full_name, party, party_short_name,
                                    is_active, is_incumbent, is_vacant, is_appointed, data_source)
SELECT v.id, v.first_name, v.last_name, v.full_name, NULL, NULL, true, true, false, v.appt, v.url
  FROM (VALUES
    ('e0045aef-b99b-5330-96fa-461e97f2e780'::uuid, 'Michael', 'Adams', 'Michael Adams', false, 'https://www.avc.edu/board-trustees')
  ) AS v(id, first_name, last_name, full_name, appt, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.id = v.id);
SET LOCAL essentials.allow_duplicate_name = 'off';

-- Reused rows (2024 NetFile filers / 2026 state-race candidates / audit-deactivated rows -- same people):
-- mark incumbent, clear any stored party.
UPDATE essentials.politicians p SET is_incumbent = true, is_active = true, party = NULL, party_short_name = NULL
 WHERE p.id IN ('f5304380-74b8-4348-91bc-33071425578f', '6f20d44c-5b15-48c4-9221-84acc37af65c', 'c6611aa8-44df-49b8-8e47-59191979597e', '36a982d9-8c67-4c49-92cf-1f90a2b50e9f')
   AND (NOT p.is_incumbent OR NOT p.is_active OR p.party IS NOT NULL OR p.party_short_name IS NOT NULL);

