    ('72c21227-0fa1-5a0c-b181-c27c05c0f067'::uuid, 'c6611aa8-44df-49b8-8e47-59191979597e'::uuid, '2024-12-01'::date, 'month', 'elected', 'CA_0221: seated per https://www.canyons.edu/administration/board/ (read 2026-09-23) -- "Mr. Fred Arnold | Trustee Area 3". Term basis: RR/CC Nov 5 2024 candidate list (lavote.gov/Apps/CandidateList/Index?id=4324) + results (results.lavote.gov/text-results/4324).'),
    ('fde26854-1d17-5dbc-8347-b68de9248ed9'::uuid, '36a982d9-8c67-4c49-92cf-1f90a2b50e9f'::uuid, '2024-12-01'::date, 'month', 'elected', 'CA_0221: seated per https://www.canyons.edu/administration/board/ (read 2026-09-23) -- "Ms. Sharlene Johnson | Trustee Area 4". Term basis: RR/CC Nov 5 2024 candidate list (lavote.gov/Apps/CandidateList/Index?id=4324) + results (results.lavote.gov/text-results/4324).'),
    ('048f1d08-2b01-5149-856e-e79bbadff8aa'::uuid, '823c68bb-f4fa-52ff-b2fe-bc626cd50aa4'::uuid, '2024-09-18'::date, 'day', 'appointed', 'CA_0221: seated per https://www.canyons.edu/administration/board/ (read 2026-09-23) -- ""appointed Carlos Guerrero to fill Board Seat No. 5, effective immediately, at its September 18 meeting" [2024] -- vacancy from the resignation of Joan MacGregor". Term basis: https://www.canyons.edu/administration/pio/newsroom/2024-09-19-bot.php.')
  ) AS v(oid, pid, ts, prec, how, src)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = v.oid AND t.politician_id = v.pid);

-- ─── 7. Nov 3 2026 races (nonpartisan: primary_party NULL), office-bound ──────────────────
INSERT INTO essentials.races (id, election_id, office_id, position_name, primary_party, seats)
SELECT v.id, 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid, v.oid, v.pos, NULL, v.seats
  FROM (VALUES
    ('faa78ca6-2b57-529a-a2bc-7c551882b24d'::uuid, 'aa206a9b-d65c-5ae4-9934-1e08a89727f3'::uuid, 'Antelope Valley Community College Board - Trustee Area 2', 1),
    ('6fa8c8df-5bb3-5bf4-9d7a-b35aab8c2049'::uuid, 'adf99f92-b4f3-5b8f-96fe-db8a6571d9ab'::uuid, 'Antelope Valley Community College Board - Trustee Area 4', 1),
    ('c619f14b-7b05-5efd-9a01-3c0ca9985b52'::uuid, '2bbf37eb-9bfe-5c1f-a8f3-1eb8b33366a2'::uuid, 'Antelope Valley Community College Board - Trustee Area 5', 1),
    ('7a69109a-baad-59ed-a5b6-616f18823b2b'::uuid, '2b54cfda-e331-50ef-86c9-8cf7b7b2e6c5'::uuid, 'Santa Clarita Community College Board - Trustee Area 1', 1),
    ('6e32cc42-b20a-5732-9241-bbaf37a687b7'::uuid, '048f1d08-2b01-5149-856e-e79bbadff8aa'::uuid, 'Santa Clarita Community College Board - Trustee Area 5', 1)
  ) AS v(id, oid, pos, seats)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.races r WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos);

INSERT INTO essentials.race_candidates
       (race_id, politician_id, full_name, first_name, last_name, is_incumbent, candidate_status, occupational_designation, source)
SELECT r.id, v.pid, v.full_name, v.first_name, v.last_name, v.inc, 'active', v.desig, v.src
  FROM (VALUES
    ('Antelope Valley Community College Board - Trustee Area 2', 'Newton Chelette', 'Newton', 'Chelette', NULL::uuid, false, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Antelope Valley Community College Board - Trustee Area 2', 'Ricardo Ortega', 'Ricardo', 'Ortega', NULL::uuid, false, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Antelope Valley Community College Board - Trustee Area 4', 'Michael R. Adams', 'Michael', 'Adams', 'e0045aef-b99b-5330-96fa-461e97f2e780'::uuid, true, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Antelope Valley Community College Board - Trustee Area 4', 'Nashon T. Mitchell', 'Nashon', 'Mitchell', NULL::uuid, false, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Antelope Valley Community College Board - Trustee Area 5', 'Pamela Ford', 'Pamela', 'Ford', NULL::uuid, false, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Antelope Valley Community College Board - Trustee Area 5', 'Barbara Gaines', 'Barbara', 'Gaines', '0151b76c-4c08-56ad-a3f3-75b96a237afc'::uuid, true, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Santa Clarita Community College Board - Trustee Area 1', 'Reza Rassool', 'Reza', 'Rassool', NULL::uuid, false, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Santa Clarita Community College Board - Trustee Area 1', 'Darlene Trevino', 'Darlene', 'Trevino', 'f5304380-74b8-4348-91bc-33071425578f'::uuid, true, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.'),
    ('Santa Clarita Community College Board - Trustee Area 5', 'Carlos Guerrero', 'Carlos', 'Guerrero', '823c68bb-f4fa-52ff-b2fe-bc626cd50aa4'::uuid, true, NULL, 'LA County Registrar-Recorder, Nov 3 2026 General Election candidate list (lavote.gov/Apps/CandidateList/Index?id=4348), nomination papers FILED. Retrieved 2026-09-23.')
  ) AS v(pos, full_name, first_name, last_name, pid, inc, desig, src)
  JOIN essentials.races r ON r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND r.position_name = v.pos
 WHERE NOT EXISTS (SELECT 1 FROM essentials.race_candidates rc WHERE rc.race_id = r.id AND lower(rc.full_name) = lower(v.full_name));

-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X0002' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry);
  IF n <> 10 THEN RAISE EXCEPTION 'expected 10 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid) AND d.district_type = 'SCHOOL' AND d.mtfcc = 'X0002';
  IF n <> 10 THEN RAISE EXCEPTION 'expected 10 SCHOOL districts, got %', n; END IF;

  -- every seat is held by exactly the trustee named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('9c307b4a-2275-5d2f-9632-edf7ec072957'::uuid, '6543f07c-92ff-5162-b0db-b8e8b36dde25'::uuid), ('aa206a9b-d65c-5ae4-9934-1e08a89727f3'::uuid, 'cd237ac3-1197-5599-9fbd-5ed34b8996a3'::uuid), ('88b6f30e-e690-5401-bc64-1cb8e3c5aa2e'::uuid, '3a48c895-ae89-5ea1-b99f-c5bb0793fc09'::uuid), ('adf99f92-b4f3-5b8f-96fe-db8a6571d9ab'::uuid, 'e0045aef-b99b-5330-96fa-461e97f2e780'::uuid), ('2bbf37eb-9bfe-5c1f-a8f3-1eb8b33366a2'::uuid, '0151b76c-4c08-56ad-a3f3-75b96a237afc'::uuid), ('2b54cfda-e331-50ef-86c9-8cf7b7b2e6c5'::uuid, 'f5304380-74b8-4348-91bc-33071425578f'::uuid), ('7ffdccf8-2511-5b73-9f6d-b2ea371b2571'::uuid, '6f20d44c-5b15-48c4-9221-84acc37af65c'::uuid), ('72c21227-0fa1-5a0c-b181-c27c05c0f067'::uuid, 'c6611aa8-44df-49b8-8e47-59191979597e'::uuid), ('fde26854-1d17-5dbc-8347-b68de9248ed9'::uuid, '36a982d9-8c67-4c49-92cf-1f90a2b50e9f'::uuid), ('048f1d08-2b01-5149-856e-e79bbadff8aa'::uuid, '823c68bb-f4fa-52ff-b2fe-bc626cd50aa4'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 10 THEN RAISE EXCEPTION 'expected 10 seats each held by its named trustee, got %', n; END IF;
  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid);
  IF n <> 10 THEN RAISE EXCEPTION 'expected 10 offices, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('9c307b4a-2275-5d2f-9632-edf7ec072957'::uuid, '6543f07c-92ff-5162-b0db-b8e8b36dde25'::uuid), ('aa206a9b-d65c-5ae4-9934-1e08a89727f3'::uuid, 'cd237ac3-1197-5599-9fbd-5ed34b8996a3'::uuid), ('88b6f30e-e690-5401-bc64-1cb8e3c5aa2e'::uuid, '3a48c895-ae89-5ea1-b99f-c5bb0793fc09'::uuid), ('adf99f92-b4f3-5b8f-96fe-db8a6571d9ab'::uuid, 'e0045aef-b99b-5330-96fa-461e97f2e780'::uuid), ('2bbf37eb-9bfe-5c1f-a8f3-1eb8b33366a2'::uuid, '0151b76c-4c08-56ad-a3f3-75b96a237afc'::uuid), ('2b54cfda-e331-50ef-86c9-8cf7b7b2e6c5'::uuid, 'f5304380-74b8-4348-91bc-33071425578f'::uuid), ('7ffdccf8-2511-5b73-9f6d-b2ea371b2571'::uuid, '6f20d44c-5b15-48c4-9221-84acc37af65c'::uuid), ('72c21227-0fa1-5a0c-b181-c27c05c0f067'::uuid, 'c6611aa8-44df-49b8-8e47-59191979597e'::uuid), ('fde26854-1d17-5dbc-8347-b68de9248ed9'::uuid, '36a982d9-8c67-4c49-92cf-1f90a2b50e9f'::uuid), ('048f1d08-2b01-5149-856e-e79bbadff8aa'::uuid, '823c68bb-f4fa-52ff-b2fe-bc626cd50aa4'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated trustee row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two trustee areas of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X0002'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X0002'
   WHERE a.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% trustee-area pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> X0002 SCHOOL district -> office -> holder)
  -- to exactly that district's own trustee(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X0002'
   WHERE me.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X0002'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own trustee(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid);
  IF n <> 5 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 5 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid);
  IF n <> 9 THEN RAISE EXCEPTION 'expected 9 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a trustee seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('d8bd2e54-6618-560d-8ad8-f45adf3f5970'::uuid, 'f358a768-2812-56f6-9164-ff1cb8a567ba'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated trustee', n; END IF;

  RAISE NOTICE 'CA_0221 applied: 2 boards, 10 polygons, 10 seats, 5 races, 9 candidates';
END $$;

COMMIT;
